#!/usr/bin/env python3
"""Write validation/REPORT.md from the results of the validation scripts."""
import json
import os
import re

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
V = os.path.join(ROOT, 'validation')


def load(path):
    p = os.path.join(V, path)
    return json.load(open(p)) if os.path.exists(p) else None


def main():
    out = ['# Lipid21 -> GROMACS: validation report', '',
           'Generated by `tools/summarize_validation.py` from the result files in this directory.',
           'Energies in kJ/mol, forces in kJ/mol/nm. Amber electrostatic energies are multiplied by',
           '138.935458 / (332.0522173 x 0.4184) = 1.0000346, the ratio of the Coulomb constants used by',
           'GROMACS and Amber (the topologies carry identical charges).', '']

    # 1. topology vs tleap
    log = os.path.join(V, 'topology_vs_tleap.log')
    if os.path.exists(log):
        txt = open(log).read()
        out += ['## 1. Topology builder vs. tleap (term by term)', '',
                '`tools/compare_prmtop.py --build`: every TAIL-HEAD-TAIL combination of the 7 Lipid21 tails and',
                '6 head groups (294), the 7 sphingomyelins ACYL-SPM-SA and cholesterol were built with tleap and',
                'compared with the topology written by `tools/lipid21_gmx.py`: atom names, types, charges, masses,',
                'LJ A/B coefficients, bonds, angles, every torsion term, impropers including atom order, 1-4 pairs',
                'with their SCEE/SCNB factors and the exclusion lists.', '', '```', txt.strip(), '```', '']

    # 2./3. molecules
    r = load('molecules/results.json')
    if r:
        ok = [m for m in r if m['ok']]
        nfr = sum(m['nframes'] for m in ok)
        out += ['## 2. GROMACS topologies as processed by grompp vs. tleap', '',
                'For each of the %d molecules the `.tpr` written by grompp was dumped (`gmx dump`) and every' % len(r),
                'interaction, with the parameters GROMACS actually assigned, compared with the prmtop.', '',
                '| variant | molecules | tpr differences | bonds | angles | torsion terms (k != 0) | impropers | 1-4 pairs (SCNB=6) | LEaP reorderings by grompp |',
                '|---|---|---|---|---|---|---|---|---|']
        labels = {'standalone': '`lipid21.ff/forcefield.itp`',
                  'amber19sb': '`amber19sb.ff` + `lipid21_params.itp`',
                  'emulate': 'LEaP numerics emulated'}
        for v, lab in labels.items():
            st = {}
            for m in ok:
                for k, x in m['variants'][v]['tpr_stats'].items():
                    st[k] = st.get(k, 0) + x
            nerr = sum(len(m['variants'][v]['tpr_errors']) for m in ok)
            nre = sum(1 for m in ok for x in m['variants'][v]['reorder_log']
                      if not x.startswith('To match AMBER LEaP ordering, reordered 0 '))
            out.append('| %s | %d | %d | %d | %d | %d | %d | %d (%d) | %s |' % (
                lab, len(ok), nerr, st['bonds'], st['angles'], st['proper_terms'], st['impropers'],
                st['pairs14'], st['pairs14_scnb6'], nre if v == 'amber19sb' else '-'))
        adj = sorted({n for m in ok for n in m['charge_adjust']})
        out += ['', 'Charge changes relative to lipid21.lib: %s (sphingomyelins only, see README).' %
                (', '.join('SPM %s -3e-6 e in %d molecules' % (n, sum(1 for m in ok if n in m['charge_adjust'])) for n in adj) or 'none'), '']
        out += ['## 3. Single-molecule energies and forces (vacuum, no cut-off)', '',
                '%d conformations: for each molecule the minimised structure and 10 frames of 450 K vacuum MD' % nfr,
                '(sander). Amber: pysander, no cut-off. GROMACS: `mdrun -rerun`, 15 nm box, plain 6 nm cut-offs',
                'without modifiers (= no cut-off). Worst case over all molecules and frames.', '',
                '"noise floor" = GROMACS vs. GROMACS for the same frames rigidly translated by (0.37, 0.53, 0.71) nm,',
                'i.e. the reproducibility of mixed-precision GROMACS itself.', '',
                '| term | RMS term size | max abs dE standalone | max abs dE amber19sb | max abs dE LEaP-emulated | noise floor |',
                '|---|---|---|---|---|---|']
        terms = list(ok[0]['variants']['standalone']['energy'])
        for t in terms:
            size = sum(m['variants']['standalone']['energy'][t]['rms_value'] for m in ok) / len(ok)
            vals = [max(m['variants'][v]['energy'][t]['max_abs'] for m in ok)
                    for v in ('standalone', 'amber19sb', 'emulate', 'standalone_shifted')]
            out.append('| %s | %.0f | %.1e | %.1e | %.1e | %.1e |' % ((t, size) + tuple(vals)))
        fl = [(v, max(m['variants'][v]['force_rms_abs'] for m in ok), max(m['variants'][v]['force_max_abs'] for m in ok))
              for v in ('standalone', 'amber19sb', 'emulate', 'standalone_shifted')]
        frms = sum(m['variants']['standalone']['force_rms_value'] for m in ok) / len(ok)
        out += ['', 'Forces (typical RMS |F| = %.0f): worst per-molecule RMS |dF| / worst max |dF|: ' % frms +
                ', '.join('%s %.3f / %.3f' % (v, a, b) for v, a, b in fl) + '.', '']

    # 4. bilayers
    b = load('bilayers/results.json')
    if b:
        out += ['## 4. Lipid21 reference bilayers (PME, single point at the 300 ns structure)', '',
                'Amber: repository `build.leap` (ff19SB, TIP3P, Lipid21, frcmod.ionsff99_tip3p), pmemd energies and',
                'sander forces. GROMACS: shipped lipid21.ff `.itp` files. Same smooth-PME discretisation in both',
                '(cut 10 A, dsum_tol 1e-5 = ewald-rtol 1e-4, order 4, identical grid), no potential modifiers, no',
                'dispersion correction. TIP3P carries the three bonds of the prmtop for this comparison only.', '',
                '| system | atoms | Bond | Angle | Dihedral | LJ-14 | Coulomb-14 | LJ (SR) | Coulomb (PME) | Potential | RMS dF lipids | RMS dF all | max dF |',
                '|---|---|---|---|---|---|---|---|---|---|---|---|---|']
        for s in b:
            if not s['ok']:
                out.append('| %s | FAILED |' % s['system'])
                continue
            c = s['compare']
            out.append('| %s | %d | %s | %.3f | %.3f | %.3f |' % (
                s['system'], s['natom'],
                ' | '.join('%+.3f' % c[k]['diff'] for k in ('Bond', 'Angle', 'Dihedral', 'LJ-14', 'Coulomb-14',
                                                           'LJ (r<1 nm)', 'Coulomb (PME)', 'Potential')),
                s['forces']['lipid']['rms_dF'], s['forces']['all']['rms_dF'], s['forces']['all']['max_dF']))
        ok = [s for s in b if s['ok']]
        out += ['', 'Values are GROMACS - Amber. Typical magnitudes: Bond ~8.6e3, Angle ~3.6e4, Dihedral ~2.1e4,',
                'Coulomb-14 ~7.5e4, Coulomb (PME) ~3.1e5 kJ/mol; RMS |F| ~ %.0f kJ/mol/nm.' %
                (sum(s['forces']['all']['rms_F'] for s in ok) / len(ok)),
                'The PME energy difference is a property of mixed-precision GROMACS, not of the topology: see 5.', '']
    pme = os.path.join(V, 'pme_precision_test.log')
    if os.path.exists(pme):
        out += ['## 5. PME energy in mixed precision', '',
                '`tools/pme_precision_test.py`. Part 1 compares both programs with an exact (numpy, double',
                'precision) Ewald sum; part 2 shows that the converged Amber energy of the POPC bilayer does not',
                'depend on the Ewald splitting while the GROMACS energy does. Forces are not affected (section 4).', '',
                '```', open(pme).read().strip(), '```', '']
    m = load('mixed_membrane/results.json')
    if m:
        out += ['## 6. Independent mixed membrane (packmol-memgen -> lipid21_pdb2gmx.py)', '',
                open(os.path.join(V, 'mixed_membrane', 'README.txt')).read().strip() if
                os.path.exists(os.path.join(V, 'mixed_membrane', 'README.txt')) else '', '',
                '| term | GROMACS | Amber | GROMACS - Amber |', '|---|---|---|---|']
        for k, v in m['compare'].items():
            out.append('| %s | %.3f | %.3f | %+.3f |' % (k, v['gmx'], v['amber'], v['diff']))
        out += [''] + ['Forces %s: RMS |F| %.1f, RMS |dF| %.4f, max |dF| %.3f kJ/mol/nm.' % (k, v['rms_F'], v['rms_dF'], v['max_dF'])
                       for k, v in m['forces'].items()] + ['']
    mds = [p for p in (os.path.join(V, 'md_popc', 'summary.txt'),
                       os.path.join(V, 'mixed_membrane', 'gmx', 'md_summary.txt')) if os.path.exists(p)]
    if mds:
        out += ['## 7. MD stability checks (GROMACS, `mdp/md_npt.mdp`, no dispersion correction)', '',
                'Unbiased runs with the shipped files: the POPC reference bilayer started from the Lipid21',
                '300 ns structure (`input_POPC_128.pdb`, same coordinates as `start.rst`; obtained in Amber with pmemd',
                'defaults, i.e. with a continuum dispersion correction), and the converted packmol-memgen mixed',
                'membrane after GROMACS minimisation.', '']
        for p in mds:
            out += ['```', open(p).read().strip(), '```', '']
    open(os.path.join(V, 'REPORT.md'), 'w').write('\n'.join(out) + '\n')
    print('wrote', os.path.join(V, 'REPORT.md'))


if __name__ == '__main__':
    main()
